import{_ as e,H as i,f as s,i as l}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"16-세션","description":"","frontmatter":{},"headers":[],"relativePath":"17-sessions.md","filePath":"17-sessions.md","lastUpdated":1778828590000}'),o={name:"17-sessions.md"};function t(n,a,d,r,c,p){return i(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="_16-세션" tabindex="-1">16-세션 <a class="header-anchor" href="#_16-세션" aria-label="Permalink to &quot;16-세션&quot;">​</a></h1><p>Grok Build는 대화를 <strong>자동으로 저장</strong>합니다.<br> 터미널에서 사용하든, Headless 모드로 사용하든, Agent 모드로 사용하든, 모든 대화는 세션(Session)이라는 단위로 저장되어 나중에 다시 불러올 수 있습니다.</p><p>이 문서는 세션이 무엇인지, 어떻게 저장되고 관리되는지, 그리고 실무에서 어떻게 활용하면 좋은지를 처음 사용자 관점에서 정리합니다.</p><hr><h2 id="세션이란-무엇인가" tabindex="-1">세션이란 무엇인가? <a class="header-anchor" href="#세션이란-무엇인가" aria-label="Permalink to &quot;세션이란 무엇인가?&quot;">​</a></h2><h3 id="세션의-개념" tabindex="-1">세션의 개념 <a class="header-anchor" href="#세션의-개념" aria-label="Permalink to &quot;세션의 개념&quot;">​</a></h3><p><strong>세션</strong>은 Grok과의 <strong>하나의 지속적인 대화</strong>를 의미합니다.</p><p>하나의 세션에는 다음과 같은 정보가 모두 저장됩니다:</p><ul><li>사용자가 입력한 모든 메시지</li><li>Grok이 답변한 모든 내용</li><li>Grok이 실행한 도구 호출(Tool call)과 그 결과</li><li>TODO 리스트(작업 목록)의 상태</li><li>파일 변경 스냅샷 (rewind 기능용)</li><li>사용한 토큰 수와 턴 수</li><li>하위 에이전트(Subagent) 세션 (사용 시)</li></ul><p>세션은 고유한 <strong>세션 ID</strong> (UUID)로 식별되며, <code>~/.grok/sessions/</code> 폴더 안에 저장됩니다.</p><h3 id="왜-세션이-중요한가" tabindex="-1">왜 세션이 중요한가? <a class="header-anchor" href="#왜-세션이-중요한가" aria-label="Permalink to &quot;왜 세션이 중요한가?&quot;">​</a></h3><ul><li>대화가 길어져도 <strong>이전 내용을 잃지 않고</strong> 이어갈 수 있습니다.</li><li>중요한 대화를 나중에 다시 불러와서 <strong>참고</strong>하거나 <strong>이어서</strong> 진행할 수 있습니다.</li><li>실수로 잘못된 방향으로 갔을 때 <strong>되돌릴 수</strong> 있습니다 (<code>/rewind</code>).</li><li>여러 프로젝트를 동시에 진행할 때 <strong>프로젝트별로 대화를 분리</strong>해서 관리할 수 있습니다.</li></ul><hr><h2 id="세션-저장-위치와-구조" tabindex="-1">세션 저장 위치와 구조 <a class="header-anchor" href="#세션-저장-위치와-구조" aria-label="Permalink to &quot;세션 저장 위치와 구조&quot;">​</a></h2><p>세션은 다음과 같은 경로에 저장됩니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.grok/sessions/&lt;인코딩된-작업-디렉토리&gt;/&lt;세션-ID&gt;/</span></span></code></pre></div><p>예를 들어, <code>/Users/leeiksang/my-project</code>에서 작업했다면:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.grok/sessions/%2FUsers%2Fleeiksang%2Fmy-project/</span></span>\n<span class="line"><span>    └── &lt;session-id&gt;/</span></span>\n<span class="line"><span>        ├── summary.json          # 세션 메타데이터 (제목, 시간, 모델 등)</span></span>\n<span class="line"><span>        ├── updates.jsonl         # 실제 대화 + 도구 호출 기록</span></span>\n<span class="line"><span>        ├── chat_history.jsonl    # 모델에 보낸 원본 메시지</span></span>\n<span class="line"><span>        ├── plan.json             # TODO 리스트 상태</span></span>\n<span class="line"><span>        ├── rewind_points.jsonl   # 되돌리기용 파일 스냅샷</span></span>\n<span class="line"><span>        └── ...</span></span></code></pre></div><p><strong>중요 파일 설명</strong>:</p><ul><li><code>summary.json</code>: 세션의 기본 정보 (제목, 생성/수정 시간, 사용 모델 등)</li><li><code>updates.jsonl</code>: 가장 중요한 파일. Grok이 실제로 사용한 모든 정보가 여기에 기록됩니다.</li><li><code>chat_history.jsonl</code>: 모델에게 보낸 실제 프롬프트 기록</li></ul><hr><h2 id="세션-시작과-종료" tabindex="-1">세션 시작과 종료 <a class="header-anchor" href="#세션-시작과-종료" aria-label="Permalink to &quot;세션 시작과 종료&quot;">​</a></h2><h3 id="새-세션-시작하기" tabindex="-1">새 세션 시작하기 <a class="header-anchor" href="#새-세션-시작하기" aria-label="Permalink to &quot;새 세션 시작하기&quot;">​</a></h3><p>Grok Build를 처음 실행하면 자동으로 새로운 세션이 생성됩니다.</p><p>대화 중간에 완전히 새로운 대화를 시작하고 싶다면:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/new</span></span></code></pre></div><p>또는 슬래시 명령어로:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/new</span></span>\n<span class="line"><span>/clear   # /new의 별칭</span></span></code></pre></div><ul><li>이전 대화 내용은 모두 초기화됩니다.</li><li>새로운 프로젝트나 완전히 다른 주제를 시작할 때 사용합니다.</li></ul><hr><h3 id="이전-세션-불러오기" tabindex="-1">이전 세션 불러오기 <a class="header-anchor" href="#이전-세션-불러오기" aria-label="Permalink to &quot;이전 세션 불러오기&quot;">​</a></h3><p>이전에 하던 대화를 다시 이어서 하고 싶다면:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/load</span></span></code></pre></div><p>세션 ID를 알고 있다면 직접 지정할 수도 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/load abc123def456...</span></span></code></pre></div><ul><li><code>/load</code>를 입력하면 저장된 세션 목록이 나오고, 원하는 세션을 선택할 수 있습니다.</li><li>별칭: <code>/resume</code></li></ul><p><strong>실전 팁</strong>:</p><ul><li>중요한 대화를 하다가 다른 작업을 해야 할 때 <code>/new</code>로 새 세션을 만들었다가, 나중에 <code>/load</code>로 불러와서 이어서 진행하는 방식이 매우 유용합니다.</li></ul><hr><h2 id="세션-압축-compact" tabindex="-1">세션 압축 (<code>/compact</code>) <a class="header-anchor" href="#세션-압축-compact" aria-label="Permalink to &quot;세션 압축 (`/compact`)&quot;">​</a></h2><p>대화가 길어지면 컨텍스트 창(토큰)이 부족해질 수 있습니다. 이때 사용하는 것이 <code>/compact</code> 명령어입니다.</p><h3 id="기본-사용법" tabindex="-1">기본 사용법 <a class="header-anchor" href="#기본-사용법" aria-label="Permalink to &quot;기본 사용법&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/compact</span></span></code></pre></div><ul><li>현재 대화 기록을 압축(요약)하여 토큰을 절약합니다.</li><li>Grok은 자동으로 대화의 중요한 부분을 남기고 불필요한 부분을 요약합니다.</li></ul><h3 id="고급-사용법" tabindex="-1">고급 사용법 <a class="header-anchor" href="#고급-사용법" aria-label="Permalink to &quot;고급 사용법&quot;">​</a></h3><p>특정 내용을 꼭 유지하고 싶을 때:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authentication</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> structure</span></span></code></pre></div><ul><li><code>keep</code> 뒤에 중요한 키워드나 문장을 적으면, 압축 과정에서 그 부분이 삭제되지 않도록 보호합니다.</li></ul><p><strong>실전 팁</strong>:</p><ul><li>대화가 50턴 이상 길어지기 시작하면 <code>/context</code>로 현재 토큰 사용량을 확인해보세요.</li><li>80% 이상 차면 <code>/compact</code>를 하는 것이 좋습니다.</li><li>중요한 기술적 결정이나 아키텍처 논의가 있었다면, <code>/compact keep ...</code>를 적극 활용하세요.</li></ul><hr><h2 id="되돌리기-기능-rewind" tabindex="-1">되돌리기 기능 (<code>/rewind</code>) <a class="header-anchor" href="#되돌리기-기능-rewind" aria-label="Permalink to &quot;되돌리기 기능 (`/rewind`)&quot;">​</a></h2><p>실수로 잘못된 방향으로 대화를 진행했을 때 유용한 기능입니다.</p><h3 id="기본-사용법-1" tabindex="-1">기본 사용법 <a class="header-anchor" href="#기본-사용법-1" aria-label="Permalink to &quot;기본 사용법&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/rewind</span></span></code></pre></div><ul><li>이전 상태로 되돌아갑니다.</li><li>파일 변경, 도구 실행, 메시지 등을 단계적으로 되돌릴 수 있습니다.</li></ul><h3 id="rewind-points" tabindex="-1">rewind_points <a class="header-anchor" href="#rewind-points" aria-label="Permalink to &quot;rewind_points&quot;">​</a></h3><p>Grok은 중요한 지점마다 자동으로 <strong>rewind point</strong>를 저장합니다. 이를 통해 대화의 특정 시점으로 쉽게 돌아갈 수 있습니다.</p><p><strong>실전 팁</strong>:</p><ul><li>큰 리팩터링을 하다가 “이 방향이 아닌 것 같아” 싶을 때 <code>/rewind</code>를 사용하면 매우 유용합니다.</li><li>rewind는 단순히 채팅 기록뿐만 아니라, 실제 파일 변경까지 되돌려줄 수 있습니다.</li></ul><hr><h2 id="세션-정보-확인-명령어" tabindex="-1">세션 정보 확인 명령어 <a class="header-anchor" href="#세션-정보-확인-명령어" aria-label="Permalink to &quot;세션 정보 확인 명령어&quot;">​</a></h2><h3 id="context" tabindex="-1"><code>/context</code> <a class="header-anchor" href="#context" aria-label="Permalink to &quot;`/context`&quot;">​</a></h3><p>현재 세션의 컨텍스트 사용량을 보여줍니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/context</span></span></code></pre></div><ul><li>현재 사용 중인 토큰 수</li><li>전체 컨텍스트 창 크기 대비 사용 비율</li><li>자동 압축이 일어날 시점</li></ul><h3 id="session-info" tabindex="-1"><code>/session-info</code> <a class="header-anchor" href="#session-info" aria-label="Permalink to &quot;`/session-info`&quot;">​</a></h3><p>세션의 상세 정보를 보여줍니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/session-info</span></span></code></pre></div><ul><li>사용 중인 모델</li><li>턴 수 (메시지 교환 횟수)</li><li>총 토큰 사용량</li><li>세션 생성/수정 시간</li><li>세션 ID</li></ul><p><strong>실전 팁</strong>:</p><ul><li><code>/context</code>는 토큰이 부족해지기 전에 미리 확인하는 용도</li><li><code>/session-info</code>는 현재 세션의 전체적인 상태를 파악할 때 유용</li></ul><hr><h2 id="여러-세션-관리-팁" tabindex="-1">여러 세션 관리 팁 <a class="header-anchor" href="#여러-세션-관리-팁" aria-label="Permalink to &quot;여러 세션 관리 팁&quot;">​</a></h2><h3 id="_1-프로젝트별-세션-분리-추천" tabindex="-1">1. 프로젝트별 세션 분리 추천 <a class="header-anchor" href="#_1-프로젝트별-세션-분리-추천" aria-label="Permalink to &quot;1. 프로젝트별 세션 분리 추천&quot;">​</a></h3><p>가능하면 <strong>프로젝트마다 별도의 세션</strong>을 사용하는 것이 좋습니다.</p><ul><li>한 세션에 너무 많은 프로젝트의 대화가 섞이면 컨텍스트가 혼란스러워집니다.</li><li><code>/new</code>로 새 세션을 만들 때, 해당 프로젝트 폴더에서 실행하면 세션이 프로젝트별로 깔끔하게 분리됩니다.</li></ul><h3 id="_2-중요한-대화는-미리-compact-해두기" tabindex="-1">2. 중요한 대화는 미리 <code>/compact</code> 해두기 <a class="header-anchor" href="#_2-중요한-대화는-미리-compact-해두기" aria-label="Permalink to &quot;2. 중요한 대화는 미리 `/compact` 해두기&quot;">​</a></h3><p>중요한 기술적 결정이나 아키텍처 논의가 오고 갔다면, <code>/compact keep ...</code>로 미리 압축해두는 것이 좋습니다.</p><h3 id="_3-세션-id-활용" tabindex="-1">3. 세션 ID 활용 <a class="header-anchor" href="#_3-세션-id-활용" aria-label="Permalink to &quot;3. 세션 ID 활용&quot;">​</a></h3><p><code>/load</code>할 때 세션 ID를 직접 입력할 수 있습니다. 중요한 세션은 미리 세션 ID를 메모해두면 나중에 쉽게 불러올 수 있습니다.</p><h3 id="_4-긴-대화는-주기적으로-정리" tabindex="-1">4. 긴 대화는 주기적으로 정리 <a class="header-anchor" href="#_4-긴-대화는-주기적으로-정리" aria-label="Permalink to &quot;4. 긴 대화는 주기적으로 정리&quot;">​</a></h3><ul><li>100턴 이상 된 대화는 <code>/compact</code>를 주기적으로 하는 것이 좋습니다.</li><li>불필요한 Thinking Block이 너무 많다면, <code>/compact</code>가 자동으로 정리해줍니다.</li></ul><hr><p>지금까지 세션 압축, 되돌리기 기능, 세션 정보 확인, 그리고 여러 세션 관리 팁을 다루었습니다.</p><hr><h2 id="subagent-세션-하위-에이전트-세션" tabindex="-1">Subagent 세션 (하위 에이전트 세션) <a class="header-anchor" href="#subagent-세션-하위-에이전트-세션" aria-label="Permalink to &quot;Subagent 세션 (하위 에이전트 세션)&quot;">​</a></h2><p>Grok Build는 <strong>Subagent</strong> (하위 에이전트) 기능을 지원합니다. 이는 하나의 메인 세션 안에서 여러 개의 하위 세션을 동시에 실행할 수 있게 해줍니다.</p><h3 id="subagent-세션이란" tabindex="-1">Subagent 세션이란? <a class="header-anchor" href="#subagent-세션이란" aria-label="Permalink to &quot;Subagent 세션이란?&quot;">​</a></h3><ul><li>메인 세션에서 특정 작업을 별도의 독립된 세션으로 분리해서 실행</li><li>예: 메인 세션에서는 전체 아키텍처를 논의하고, Subagent에서는 특정 모듈의 구현을 맡김</li><li>각 Subagent는 독립적인 컨텍스트를 가지기 때문에, 메인 세션의 컨텍스트를 과도하게 소비하지 않음</li></ul><h3 id="subagent-사용-예시" tabindex="-1">Subagent 사용 예시 <a class="header-anchor" href="#subagent-사용-예시" aria-label="Permalink to &quot;Subagent 사용 예시&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/subagent start &quot;Payment module refactoring&quot;</span></span></code></pre></div><p>이렇게 하면 별도의 하위 세션이 생성되고, 그 안에서 독립적으로 작업할 수 있습니다.</p><p>Subagent 세션은 <code>subagents/</code> 폴더 안에 별도로 저장되며, 필요할 때 메인 세션으로 결과를 가져올 수 있습니다.</p><hr><h2 id="세션-공유-및-내보내기" tabindex="-1">세션 공유 및 내보내기 <a class="header-anchor" href="#세션-공유-및-내보내기" aria-label="Permalink to &quot;세션 공유 및 내보내기&quot;">​</a></h2><h3 id="세션-공유" tabindex="-1">세션 공유 <a class="header-anchor" href="#세션-공유" aria-label="Permalink to &quot;세션 공유&quot;">​</a></h3><p>Grok Build는 세션을 다른 사람과 공유할 수 있는 기능을 지원합니다.</p><ul><li><code>/session-info</code>에서 세션 ID를 확인</li><li>세션 폴더 자체를 압축해서 공유 가능</li><li>일부 환경에서는 세션 URL 공유 기능도 지원</li></ul><h3 id="세션-내보내기" tabindex="-1">세션 내보내기 <a class="header-anchor" href="#세션-내보내기" aria-label="Permalink to &quot;세션 내보내기&quot;">​</a></h3><p>중요한 대화 내용을 보존하고 싶을 때:</p><ul><li><code>updates.jsonl</code> 또는 <code>chat_history.jsonl</code> 파일을 직접 복사</li><li><code>/compact</code>로 정리한 후 중요한 부분만 남겨서 보관</li></ul><p><strong>실전 팁</strong>: 중요한 기술적 결정이 오고 간 대화는, <code>/compact keep ...</code>로 정리한 뒤 세션 폴더를 백업해두는 것을 추천합니다.</p><hr><h2 id="고급-세션-관리" tabindex="-1">고급 세션 관리 <a class="header-anchor" href="#고급-세션-관리" aria-label="Permalink to &quot;고급 세션 관리&quot;">​</a></h2><h3 id="rewind-상세" tabindex="-1">Rewind 상세 <a class="header-anchor" href="#rewind-상세" aria-label="Permalink to &quot;Rewind 상세&quot;">​</a></h3><p><code>/rewind</code>는 단순히 채팅 기록을 되돌리는 것이 아니라, <strong>파일 변경까지 되돌릴 수</strong> 있습니다.</p><ul><li>Grok이 파일을 수정했을 때, rewind를 하면 해당 파일도 이전 상태로 복원됩니다.</li><li><code>rewind_points.jsonl</code>에 중요한 시점들이 자동으로 기록됩니다.</li></ul><h3 id="compaction-checkpoints" tabindex="-1">Compaction Checkpoints <a class="header-anchor" href="#compaction-checkpoints" aria-label="Permalink to &quot;Compaction Checkpoints&quot;">​</a></h3><p>자동 압축이 일어날 때마다 <code>compaction_checkpoints/</code> 폴더에 이전 상태가 저장됩니다.</p><ul><li>압축 후에도 이전 대화의 일부를 복원할 수 있는 안전장치</li><li>필요할 경우 이전 checkpoint로 되돌아갈 수 있음</li></ul><h3 id="parent-session" tabindex="-1">Parent Session <a class="header-anchor" href="#parent-session" aria-label="Permalink to &quot;Parent Session&quot;">​</a></h3><p>다른 세션에서 이어서 시작한 세션은 <code>summary.json</code>에 <code>parent_session</code> 정보가 남습니다.</p><ul><li>“이 대화는 원래 어떤 세션에서 이어진 것인가?”를 추적할 수 있습니다.</li></ul><hr><h2 id="전체-세션-가이드-마무리" tabindex="-1">전체 세션 가이드 마무리 <a class="header-anchor" href="#전체-세션-가이드-마무리" aria-label="Permalink to &quot;전체 세션 가이드 마무리&quot;">​</a></h2><h3 id="세션-관리-추천-전략" tabindex="-1">세션 관리 추천 전략 <a class="header-anchor" href="#세션-관리-추천-전략" aria-label="Permalink to &quot;세션 관리 추천 전략&quot;">​</a></h3><ol><li><p><strong>프로젝트별 세션 분리</strong></p><ul><li>가능하면 프로젝트마다 별도의 세션을 유지하세요.</li></ul></li><li><p><strong>중요 대화는 주기적으로 정리</strong></p><ul><li><code>/compact keep ...</code>를 활용해서 핵심 내용을 보호하면서 토큰을 관리하세요.</li></ul></li><li><p><strong>되돌리기 적극 활용</strong></p><ul><li>큰 변경을 할 때는 <code>/rewind</code>를 두려워하지 마세요. 안전장치가 잘 되어 있습니다.</li></ul></li><li><p><strong>Subagent 활용</strong></p><ul><li>큰 작업은 Subagent로 분리해서 메인 세션의 컨텍스트를 보호하세요.</li></ul></li><li><p><strong>세션 백업</strong></p><ul><li>중요한 대화는 세션 폴더를 주기적으로 백업해두세요.</li></ul></li></ol><hr><p><strong>16-세션.md 끝</strong></p><p>여기까지 Grok Build의 세션 관리 기능을 전반적으로 정리했습니다.</p><p>세션은 Grok Build의 가장 기본적이면서도 가장 강력한 기능 중 하나입니다.<br> 잘 활용하면 대화의 연속성을 유지하면서도, 토큰을 효율적으로 관리하고, 실수로부터 안전하게 작업할 수 있습니다.</p><p>세션 관리를 잘하는 것은 곧 <strong>Grok Build를 잘 사용하는 것</strong>의 시작이라고 할 수 있습니다.</p><p>이 문서에서 다루지 않은 더 고급 기능이나 특정 상황에서의 세션 관리 팁이 필요하시면 언제든 말씀해주세요.</p><hr><p><em>이 가이드는 실무에서 세션을 효율적으로 관리했던 경험을 바탕으로 작성되었습니다.</em></p><ul><li>Subagent 세션 (하위 에이전트 세션)</li><li>세션 공유 및 내보내기</li><li>고급 세션 관리 (rewind 상세, compaction checkpoints)</li><li>전체 세션 가이드 마무리</li></ul><hr><ul><li>세션 압축 (<code>/compact</code>)</li><li>되돌리기 기능 (<code>/rewind</code>)</li><li>세션 정보 확인 (<code>/context</code>, <code>/session-info</code>)</li><li>여러 세션 관리 팁</li></ul><hr>',130)])])}const g=e(o,[["render",t]]);export{u as __pageData,g as default};
